<script setup lang="ts">
import{onMounted,ref}from'vue';import Button from'primevue/button';import InputText from'primevue/inputtext';import Textarea from'primevue/textarea';import ToggleSwitch from'primevue/toggleswitch';import{getAdminReviewForm,saveAdminReviewForm,type AdminReviewForm}from'@/api/admin'
const props=defineProps<{token:string;id:number|null}>();const emit=defineEmits<{saved:[];cancel:[]}>();const form=ref<AdminReviewForm>({author:'',role:'',text:'',rating:5,position:0,isPublished:false});const loading=ref(false);const error=ref('')
onMounted(async()=>{if(!props.id)return;loading.value=true;try{form.value=await getAdminReviewForm(props.token,props.id)}catch(e){error.value=e instanceof Error?e.message:'Не удалось открыть форму'}finally{loading.value=false}})
async function save(){error.value='';const missing=[!form.value.author.trim()&&'автор',!form.value.text.trim()&&'текст отзыва'].filter(Boolean);if(missing.length){error.value=`Не хватает обязательных полей: ${missing.join(', ')}`;return};loading.value=true;try{await saveAdminReviewForm(props.token,form.value);emit('saved')}catch(e){error.value=e instanceof Error?e.message:'Не удалось сохранить отзыв'}finally{loading.value=false}}
</script>
<template><section class="form"><div class="heading"><div><p class="eyebrow">{{id?'Редактирование':'Новый отзыв'}}</p><h2>{{id?(form.author||'Отзыв'):'Добавить отзыв'}}</h2></div><Button label="Закрыть" text @click="$emit('cancel')"/></div><p v-if="error" class="form-error">{{error}}</p><div class="two"><label>Автор *<InputText v-model="form.author"/></label><label>Подпись<InputText v-model="form.role" placeholder="родитель или название программы"/></label></div><label>Текст отзыва *<Textarea v-model="form.text" rows="7" auto-resize/></label><div class="rating-field"><strong>Оценка</strong><div class="stars" role="radiogroup" aria-label="Оценка отзыва"><button v-for="star in 5" :key="star" type="button" role="radio" :aria-checked="form.rating===star" :aria-label="`${star} из 5`" @click="form.rating=star">{{star<=form.rating?'★':'☆'}}</button><span>{{form.rating}} из 5</span></div></div><div class="publish"><div><strong>Показывать на сайте</strong><small>{{form.isPublished?'Отзыв опубликован':'Сохранится как черновик'}}</small></div><ToggleSwitch v-model="form.isPublished"/></div><div class="actions"><Button :label="id?'Сохранить изменения':'Добавить отзыв'" :loading="loading" @click="save"/><Button label="Отмена" text @click="$emit('cancel')"/></div></section></template>
<style scoped>.form{display:grid;gap:1.25rem}.heading,.publish{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.heading h2{margin:0}.form label,.rating-field{display:grid;gap:.45rem;font-weight:700}.two{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.stars{display:flex;align-items:center;gap:.15rem}.stars button{border:0;padding:.1rem;background:transparent;color:#f2a900;font-size:2rem;line-height:1;cursor:pointer}.stars button:hover{transform:scale(1.12)}.stars span{margin-left:.6rem;color:#647067;font-size:.9rem;font-weight:500}.publish{align-items:center;padding:1rem;background:#e9f3ef;border-radius:12px}.publish div{display:grid}.actions{display:flex;gap:.5rem;border-top:1px solid #eee;padding-top:1rem}@media(max-width:650px){.two{grid-template-columns:1fr}}</style>
